export async function createHooks(
  cwd: string,
  worktree: string,
  client: OpenCodeClient,
  pluginRoot?: string,
  options?: { skipInit?: boolean },
): Promise<Hooks> {
  const state: AideState = {
    initialized: false,
    binary: null,
    cwd,
    worktree,
    pluginRoot: pluginRoot || null,
    skipInit: options?.skipInit ?? false,
    sessionState: null,
    memories: null,
    welcomeContext: null,
    initializedSessions: new Set(),
    processedMessageParts: new Set(),
    pendingSkillsContext: null,
    lastUserPrompt: null,
    sessionInfoMap: new Map(),
    client,
    pruningTrackers: new SessionPruningTrackers(cwd),
    contextSessions: new Set(),
  };

  // Run one-time initialization (directories, binary, config)
  initializeAide(state);

  try {
    await client.app.log({
      body: {
        service: "aide",
        level: "info",
        message: `aide hooks init: cwd=${state.cwd} worktree=${state.worktree} pluginRoot=${state.pluginRoot ?? "unknown"} binary=${state.binary ?? "not-found"} skipInit=${state.skipInit}`,
      },
    });
